head.script:
scwin.trigger1_onclick = function(e) {
    grid1.setCellData(1, 1, "test data!!!");
};
scwin.trigger2_onclick = function(e) {
    alert(grid1.getCellData(1, 1));
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플 실행 후 2번째 row의 checkbox를 클릭 후 '4444'값의 +기호를 클릭하여 drilldown한다.
    //1. After running the sample, click on the checkbox in the second row and then drill down by clicking the + sign of the '4444' value.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_cell_1_0').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_plus')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 2번째 row에 체크된 checkbox가 유지되어 보여진다.
    //1. The checked checkbox in the second row is maintained and shown.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_cell_1_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 그다음 상단의 '1111'값의 +기호를 클릭한다.
    //2. Then click the + sign of the '1111' value at the top.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_plus')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 4번째 row에 체크된 checkbox가 유지되어 보여진다. (이전에는 1111값 하위의 2222값에 checkbox가 체크되어 보여짐)
    //2. The checked checkbox in the fourth row is maintained and shown. (Previously, the checkbox was checked in the value 2222 below the value 1111)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_cell_3_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 23-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
